// Anti-alluvione: con il polling al minuto, un workflow rotto genererebbe
// 1440 messaggi al giorno e finiresti per silenziare il bot — cioe' l'opposto
// di quello che serve. La memoria statica sopravvive fra le esecuzioni.
const SILENZIO_MIN = 30;

const memoria = $getWorkflowStaticData('global');
memoria.visti = memoria.visti || {};

const e = $json || {};
const wf = e.workflow || {};
const ex = e.execution || {};

const nome = String(wf.name || wf.id || 'workflow ignoto');
const chiave = 'wf_' + (wf.id || nome);
const adesso = Date.now();

const ultimo = Number(memoria.visti[chiave] || 0);
if (adesso - ultimo < SILENZIO_MIN * 60000) return [];   // già avvisato

memoria.visti[chiave] = adesso;

const msg = String(ex.error?.message || 'errore non descritto').slice(0, 400);
const nodo = ex.lastNodeExecuted ? '\nNodo: ' + ex.lastNodeExecuted : '';
const link = ex.url ? '\n' + ex.url : '';

return [{ json: {
    text: '🔴 ' + nome + '\n' + msg + nodo + link +
          '\n\n(silenzio per ' + SILENZIO_MIN + ' min su questo workflow)',
    disable_web_page_preview: true,
}}];

// Quanti giorni di silenzio sono accettabili per ciascuna fonte.
// Telegram e app non ci sono: sei tu a scriverle, il silenzio e' normale.
const ATTESO_GG = { push: 7, gmail: 30, outlook: 30 };
// La lettura copre gli ultimi 60 giorni: una fonte senza righe in quella
// finestra e' silenziosa da almeno tanto.
const FINESTRA_GG = 60;

const MAX_DA_VERIFICARE = 5;

const tx = $('Leggi Transazioni').all().map(i => i.json).filter(r => r.id !== undefined);
const oggi = new Date();
const gg = (d) => (oggi - new Date(d)) / 86400000;

const problemi = [];

// --- fonti silenziose ---
for (const [fonte, limite] of Object.entries(ATTESO_GG)) {
  const righe = tx.filter(r => String(r.fonte) === fonte && r.data_inserimento);

  if (!righe.length) {
    problemi.push('• ' + fonte + ': nessun movimento da oltre ' + FINESTRA_GG + ' giorni');
    continue;
  }

  const ultima = righe
    .map(r => String(r.data_inserimento))
    .sort()
    .pop();

  const giorni = Math.floor(gg(ultima));
  if (giorni > limite) {
    problemi.push('• ' + fonte + ': nessun movimento da ' + giorni + ' giorni');
  }
}

// --- code che si accumulano ---
const daVerificare = tx.filter(r => String(r.stato) === 'da_verificare').length;
if (daVerificare > MAX_DA_VERIFICARE) {
  problemi.push('• ' + daVerificare + ' movimenti da verificare in attesa');
}

const atteseVecchie = tx.filter(r =>
  String(r.stato) === 'attesa' && r.data_evento && gg(r.data_evento) > 10).length;
if (atteseVecchie) {
  problemi.push('• ' + atteseVecchie + ' addebiti previsti scaduti da oltre 10 giorni');
}

// Nessun problema: silenzio. La conferma che la sentinella funziona arriva
// dal report settimanale, che elenca lo stato delle fonti.
if (!problemi.length) return [];

return [{ json: {
    text: '⚠️ Controllo giornaliero\n\n' + problemi.join('\n'),
}}];
